def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final move: defection is weakly dominant when there is no future response.
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = sum(1 for x in op if x == 'D')
    my_d = sum(1 for x in my if x == 'D')

    w = min(n, 12)
    recent_d = sum(1 for x in op[-w:] if x == 'D')

    # Estimate how the opponent reacts to our previous action.
    # op[i] is treated as a response to my[i-1].
    pc = pd = unprovoked_d = punished_d = 0
    for i in range(1, n):
        if my[i - 1] == 'C':
            pc += 1
            if op[i] == 'D':
                unprovoked_d += 1
        else:
            pd += 1
            if op[i] == 'D':
                punished_d += 1

    # Clearly hostile opponents: always defect against them to avoid 0s.
    if opp_d == n:
        return 'D'

    if n >= 15 and opp_d * 10 > n * 6:
        return 'D'

    if n >= 10 and recent_d * 10 >= w * 7:
        return 'D'

    # Many defections while we were cooperating: exploitative or unresponsive.
    if pc >= 12 and unprovoked_d * 10 >= pc * 4:
        return 'D'

    # Late in a match, if opponent has substantially more defections than us,
    # stop being generous.
    if n >= 55 and opp_d > my_d + 4:
        return 'D'

    last_opp = op[-1]
    prev_my = my[-2] if n >= 2 else 'C'

    if last_opp == 'D':
        # If opponent likely punished our previous defection and has not been
        # too hostile recently, cooperate once to apologize and reset.
        if prev_my == 'D' and recent_d <= 3:
            return 'C'

        # Unprovoked or hostile defection: punish.
        return 'D'

    # Opponent cooperated.
    # If our action two rounds ago was D and they still cooperated, they may be
    # exploitable. Continue only if they are clearly cooperative overall and
    # have a low history of punishing our defections.
    if prev_my == 'D':
        if recent_d <= 2 and opp_d * 10 <= n * 3:
            if punished_d * 10 <= pd * 3:
                return 'D'
        return 'C'

    # Strong evidence from history that this opponent rarely punishes our D and
    # is otherwise cooperative: exploit opportunistically.
    if pd >= 6 and punished_d * 10 <= pd * 2 and recent_d <= 3 and opp_d * 10 <= n * 4:
        return 'D'

    return 'C'
